package com.tnc.tnc.life.routes.mech;
import com.tnc.tnc.adventure.AdventureGameTests;
import com.tnc.tnc.life.routes.*;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.core.BlockPos;
@GameTestHolder("tncroute") @PrefixGameTestTemplate(false)
public final class ZeroGameTests {
    private static ItemStack equip(net.minecraft.server.level.ServerPlayer p,int mana){var suit=new ItemStack(RouteContent.item("mana_mech"));p.setItemSlot(EquipmentSlot.CHEST,suit);RouteChargeLedger.get(p.serverLevel()).deposit(suit,12000,mana);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(RouteContent.item("zero_spellgun")));p.startUsingItem(InteractionHand.MAIN_HAND);return suit;}
    @GameTest(template="mirror_test_empty",timeoutTicks=40) public static void missingSuitAndEmptyReactorCannotFire(GameTestHelper h){var p=AdventureGameTests.player(h);h.assertTrue(!ZeroGunItem.fire(p),"no suit no shot");var suit=equip(p,0);h.assertTrue(!ZeroGunItem.fire(p)&&RouteChargeLedger.get(h.getLevel()).amount(suit)==0,"empty reactor cannot mint spells");h.succeed();}
    @GameTest(template="mirror_test_empty",timeoutTicks=40) public static void realWaterCannonAndCadenceUseOneReactorDebit(GameTestHelper h){var p=AdventureGameTests.player(h);var suit=equip(p,1000);var pos=h.absolutePos(new BlockPos(3,2,3));p.setPos(pos.getX(),pos.getY(),pos.getZ());h.assertTrue(ZeroGunItem.fire(p),"water shot accepted");var shots=h.getLevel().getEntitiesOfClass(com.tnc.tnc.magic.water.TNWaterBoltEntity.class,p.getBoundingBox().inflate(3),e->e.getOwner()==p&&e.tier()==2);h.assertTrue(shots.size()==1,"actual water cannon tier2 entity");ZeroGunItem.fire(p);h.assertTrue(RouteChargeLedger.get(h.getLevel()).amount(suit)==928,"same tick cannot charge or spawn twice");shots.forEach(Entity::discard);h.succeed();}
    @GameTest(template="mirror_test_empty",timeoutTicks=40) public static void actualGreatFireballAndWindEntitiesAreReused(GameTestHelper h){var p=AdventureGameTests.player(h);var at=p.getEyePosition();var fire=ZeroSpellPayload.prepare(p,ZeroRules.Form.FIRE,at);var wind=ZeroSpellPayload.prepare(p,ZeroRules.Form.WIND,at);h.assertTrue(fire instanceof com.tnc.tnc.magic.fire.TNFireBoltEntity f&&f.spellPath().equals("great_fireball"),"same fireball spell");h.assertTrue(wind instanceof com.tnc.tnc.magic.wind.WindBallEntity w&&w.tier()==2,"same great wind ball");h.succeed();}
    @GameTest(template="mirror_test_empty",timeoutTicks=360) public static void fullReactorActuallySustainsMoreThanFifteenSeconds(GameTestHelper h){var p=AdventureGameTests.player(h);var suit=equip(p,12000);var at=h.absolutePos(new BlockPos(4,3,4));p.setPos(at.getX(),at.getY(),at.getZ());suit.getOrCreateTag().putLong("MechVent",MechCombat.now(p)+10000);for(int i=0;i<166;i++)h.runAtTickTime(i*2,()->h.assertTrue(ZeroGunItem.fire(p),"rated continuous shot must succeed"));h.runAtTickTime(332,()->{h.assertTrue(suit.getTag().getInt("ZeroShots")==166,"166 real accepted projectile spawns");h.assertTrue(RouteChargeLedger.get(h.getLevel()).amount(suit)==48&&!ZeroGunItem.fire(p),"endurance ends only when less than72M remain");h.succeed();});}
    @GameTest(template="mirror_test_empty",timeoutTicks=40) public static void recipeLoadsWithinTheFourSlotForgeCapacity(GameTestHelper h){var id=net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("tnc","zero_spellgun");var recipe=h.getLevel().getRecipeManager().byKey(id).orElseThrow();h.assertTrue(recipe instanceof com.tnc.tnc.production.ManaForgeRecipe r&&r.inputs().size()==4&&r.mana()<=com.tnc.tnc.production.MagicForgeBlockEntity.MAX_CHARGE&&r.getResultItem(h.getLevel().registryAccess()).is(RouteContent.item("zero_spellgun")),"obtainable forge recipe fits actual machine");h.succeed();}
}
